import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        int k = (int) nextLong();
        List<Integer> ones = new ArrayList<>();
        for (int i = 0; i < s.length(); i++)
            if (s.charAt(i) == '1') ones.add(i);
        String best = null;
        // Each window of k consecutive ones, trimmed to start and end on a one.
        for (int i = 0; i + k <= ones.size(); i++) {
            String z = s.substring(ones.get(i), ones.get(i + k - 1) + 1);
            if (best == null || z.length() < best.length() || (z.length() == best.length() && z.compareTo(best) < 0))
                best = z;
        }
        System.out.println(best);
    }
}

