import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func nextToken() string {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	s := nextToken()
	k := int(nextInt())
	var ones []int
	for i := 0; i < len(s); i++ {
		if s[i] == '1' {
			ones = append(ones, i)
		}
	}
	best := ""
	// Each window of k consecutive ones, trimmed to start and end on a one.
	for i := 0; i+k <= len(ones); i++ {
		z := s[ones[i] : ones[i+k-1]+1]
		if best == "" || len(z) < len(best) || (len(z) == len(best) && z < best) {
			best = z
		}
	}
	fmt.Println(best)
}
